<template>
  <div class="recharge-detail">
    <!-- <title-line :title="title" /> -->
    <div class="title-line">
      <div class="left-arrow" @click="onClickLeft" />
      <div class="title-name">{{ title }}</div>
    </div>
    <div class="contentBox">
      <div class="title-line">
        <div class="order-num">
          <div class="label">{{ $t('ctjl.ctjl03') }}：</div>
          <div class="value">{{ params.pcode }}</div>
        </div>
        <div class="order-status">{{params.pstatus}}</div>
      </div>
      <div class="box-span">
        <div class="box-item">
          <div class="label">{{ $t('ctjl.ctjl04') }}</div>
          <div class="value">{{ params.pdirect }}</div>
        </div>
        <div class="box-item">
          <div class="label">{{ currentIndex==='0'?$t('ctjl.ctjl05'):$t('ctjl.ctjl12') }}</div>
          <div class="value" style="color: rgba(255,255,255,1);"><div class="icon-usdt" />USDT</div>
        </div>
      </div>
      <div class="other-info">
        <template>
         
        </template>
        <div v-for="(item,index) in dataList" :key="index" class="item">
          <div class="label">{{ item.label }}</div>
          <div :class="(index===2 || index===3 || index===4)?'value yellow-text':'value'">{{ item.value }}</div>
        </div>
      </div>

    </div>
  </div>
</template>
<script>
import TitleLine from '../modules/TitleLine'
export default {
  name: 'RechargeDetail',
  components: {
    TitleLine
  },
  data() {
    return {
      currentIndex: null,
      title: this.$t('ctjl.ctjl13'),
      dataList: [
        { label: this.$t('ctjl.ctjl06'), value: '' },
        { label: this.$t('ctjl.ctjl07'), value: '' },
        { label: this.$t('ctjl.ctjl08'), value: '' },
        { label: this.$t('ctjl.ctjl09'), value: '' },
        { label: this.$t('ctjl.ctjl10'), value: '' },
        { label: this.$t('ctjl.ctjl111'), value: '' },
        { label: this.$t('ctjl.ctjl112'), value: '' },
        { label: this.$t('ctjl.ctjl11'), value: '' }
      ],
      params: {
      }
    }
  },
  mounted() {
    this.currentIndex = this.$route.query.currentIndex
    localStorage.getItem('rechargeDetail') && (this.params = JSON.parse(localStorage.getItem('rechargeDetail')))
    this.dataList[0].value = this.params.protocal
    this.dataList[1].value = this.params.handingfee
    this.dataList[2].value = this.params.cmons
    this.dataList[3].value = this.params.pmons
    this.dataList[4].value = this.params.trnhash&&(this.params.trnhash.slice(0, 6) + '****' + this.params.trnhash.slice(this.params.trnhash.length - 6, this.params.trnhash.length))
    this.dataList[5].value = this.params.uidto&&(this.params.uidto.slice(0,6)+'****'+this.params.uidto.slice(this.params.uidto.length-6,this.params.uidto.length))
    this.dataList[6].value = this.params.auditremark
    this.dataList[7].value = this.params.paytime
    this.title = this.params.pdirect === '提现' ? this.$t('ctjl.ctjl14') : this.$t('ctjl.ctjl13')
    if(this.params.pdirect !== '提现'){
      this.dataList.splice(5, 2)
      // this.dataList.delete(5)
    }
  },
  methods: {
    deepCopy(obj) {
      return JSON.parse(JSON.stringify(obj))
    },
    onClickLeft(){
      this.$router.push({ path: '/rechargeRecord', query: { currentIndex: this.params.pdirect === '提现'?1:0 } })
    }
  }
}
</script>
<style lang="less" scoped>
  .recharge-detail {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .title-line {
      flex: 1;
      display: flex;
      flex-direction: row;
      align-items: center;
      // background-color: #fff;
      color: #fff;
      justify-content: space-between;
      min-height: 88px;
      position: relative;
      z-index: 2021;
      padding: 0 30px;
      .left-arrow{
          position: absolute;
          background-image: url('~@/assets/portal/返回1.svg');
          background-position: 0% 0%;
          background-size: 100% 100%;
          background-repeat: no-repeat;
          height: 48px;
          width: 48px;
      }
      .title-name{
          flex: 1;
          font-family: PingFangSC-Medium;
          font-size: 36px;
          color: #FFFFFF;
          letter-spacing: 0;
          text-align: center;
          font-weight: 500;
      }
    }
    .contentBox {
      // height: 712px;
      margin: 28px;
      padding: 32px 28px;
      background: rgba(241, 229, 255,0.12);
      border-radius: 16px;
      .title-line {
        display: flex;
        justify-content: space-between;
        align-items: center;
        .order-num {
        display: flex;
        height: 48px;
        font-family: PingFangSC-Semibold;
        font-size: 32px;
        color: #FFFFFF;
        letter-spacing: 0;
        line-height: 48px;
        font-weight: 600;
        }
        .order-status {
          display: flex;
          font-family: PingFangSC-Semibold;
          font-size: 28px;
          color: #FFFFFF;
          text-align: center;
          font-weight: 600;
        }
      }
      .box-span {
        display: flex;
        justify-content: space-between;
        margin-top: 32px;
        .box-item {
          width: 280px;
          height: 112px;
          background: rgba(0,0,0,0.30);
          border-radius: 12px;
          padding: 24px 0 0 28px;
          .label {
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: rgba(255, 255, 255, 0.75);
            letter-spacing: 0;
            font-weight: 400;
          }
          .value {
            display: flex;
            align-items: center;
            margin-top: 8px;
            font-family: PingFangSC-Semibold;
            font-size: 28px;
            color: #24EE89;
            letter-spacing: 0;
            line-height: 40px;
            font-weight: 600;
            .icon-usdt {
              width: 28px;
              height: 28px;
              margin-right: 12px;
              background: url('~@/assets/portal/USDT.png') no-repeat center;
              background-size: 100% 100%;
            }
          }
        }
      }
      .other-info {
        margin-top: 8px;
        .item {
          display: flex;
          justify-content: space-between;
          align-items: center;
          height: 80px;
          .label {
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: rgba(255, 255, 255,0.75);
            letter-spacing: 0;
            font-weight: 400;
          }
          .value {
            font-family: PingFangSC-Semibold;
            font-size: 28px;
            color: #FFFFFF;
            letter-spacing: 0;
            text-align: right;
            line-height: 40px;
            font-weight: 600;
          }
        }
      }
    }
    .yellow-text {
      color: rgba(255,215,0,1) !important;
    }
  }
</style>
